<script>import {onMount,createEventDispatcher} from 'svelte';import {start} from './store.js';const dispatch=createEventDispatcher();let workflows=[],workflowName='',workflowVersion='1',inputs='{}',saving=false,error='';onMount(async()=>{try{const r=await fetch('/ailtire/workflow/list');const b=await r.json();workflows=(b.categories||[]).flatMap(c=>c.workflows||[])}catch(e){error=e.message}});$: selected=workflows.find(w=>w.name===workflowName&&String(w.version||'1')===String(workflowVersion));async function submit(){saving=true;try{const execution=await start({workflowName,workflowVersion,inputs});dispatch('started',execution)}catch(e){error=e.message}finally{saving=false}}</script>
<form on:submit|preventDefault={submit}><h2>Launch workflow</h2><label>Workflow<select bind:value={workflowName} required><option value="">Select workflow</option>{#each workflows as workflow}<option value={workflow.name}>{workflow.name} v{workflow.version||'1'}</option>{/each}</select></label><label>Version<input bind:value={workflowVersion} required/></label>{#if selected?.inputs}{#each Object.entries(selected.inputs) as [name,field]}<label title={field.description||name}>{name}{#if field.required} *{/if}<input required={field.required} placeholder={field.type||'string'}/><small>{field.description||''}</small></label>{/each}{/if}<label>Inputs JSON<textarea bind:value={inputs}></textarea></label>{#if error}<p class="error">{error}</p>{/if}<button disabled={saving}>{saving?'Launching…':'Launch workflow'}</button></form><style>form{display:grid;gap:12px}label{display:grid;gap:4px}select,input,textarea{font:inherit;padding:8px;border:1px solid #d7dce3;border-radius:6px}textarea{min-height:100px}.error{color:#b42318}small{color:#697586}</style>
